class Cell:
    def __init__(self):
        self._value = None
        self._previous_value = None
        self._callbacks = set()
        self._dependents = set()
        self._inputs = []

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        self._propagate()

    def add_callback(self, callback):
        self._callbacks.add(callback)

    def remove_callback(self, callback):
        self._callbacks.discard(callback)

    def _add_dependent(self, dependent):
        self._dependents.add(dependent)

    def _recompute(self):
        pass

    def _propagate(self):
        # Recompute all affected cells in dependency order so the system
        # reaches a new stable state, then fire callbacks once per cell,
        # only if the value changed from the previous stable state.
        affected = self._collect_affected()
        ordered = self._topological_order(affected)
        for cell in ordered:
            cell._recompute()
        for cell in ordered:
            if cell._value != cell._previous_value:
                for callback in list(cell._callbacks):
                    callback(cell._value)

    def _collect_affected(self):
        affected = []
        seen = set()
        queue = [self]
        while queue:
            cell = queue.pop()
            for dependent in cell._dependents:
                if dependent not in seen:
                    seen.add(dependent)
                    affected.append(dependent)
                    queue.append(dependent)
        return affected

    def _topological_order(self, affected):
        remaining = set(affected)
        ordered = []
        while remaining:
            progressed = False
            for cell in list(remaining):
                if all(cell_input not in remaining for cell_input in cell._inputs):
                    ordered.append(cell)
                    remaining.discard(cell)
                    progressed = True
            if not progressed:
                # Dependency cycle: process the rest in arbitrary order.
                ordered.extend(remaining)
                break
        return ordered


class InputCell(Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value


class ComputeCell(Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = list(inputs)
        self._compute_function = compute_function
        for cell_input in self._inputs:
            cell_input._add_dependent(self)
        self._recompute()

    def _recompute(self):
        self._previous_value = self._value
        self._value = self._compute_function(
            [cell_input.value for cell_input in self._inputs]
        )

